/// The host side of this document's typed `<invoke type="sce-host-clock-now">`s (SCE
/// Accepted Subset §2.12). Register it with `registerStaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker`.
public protocol StaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker: AnyObject {
    /// §scxml-6.4: begin `<invoke id="clock">`. `token` names this start; a
    /// host that finishes later hands it back to `completeStaticInvokeTreeSceSynthInvokeWorkerClock`
    /// (or `completeHostInvoke`). A non-nil answer completes the invocation now.
    func startClock(token: UInt64) -> StaticInvokeTreeSceSynthInvokeWorkerClockResult?

    /// §scxml-6.4: `<invoke id="clock">`'s state exited while the start `token`
    /// names was still running. Stop it.
