/// Registers `invoker` as the handler for `type="sce-host-clock-now"`.
public func registerStaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker(on engine: Engine<StaticInvokeTreeSceSynthInvokeWorkerPolicy>, invoker: StaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker) throws(HostRegistrationError) {
    try engine.registerInvoker("sce-host-clock-now") { event in
        switch event {
        case .start(let start):
            if start.invokeID.utf8.elementsEqual("clock".utf8) {
                if let result = invoker.startClock(token: start.token) {
                    return .done(result.wire)
                }
                return nil
            }
            return nil
        case .cancel(let cancel):
            if cancel.invokeID.utf8.elementsEqual("clock".utf8) {
                invoker.cancelClock(token: cancel.token)
                return nil
            }
            return nil
        }
    }
}

/// Completes `<invoke id="clock">`'s start `token` with its record:
/// `completeHostInvoke` with the record's JSON, so a stale or unknown token is
/// refused the same way (false).
@discardableResult
public func completeStaticInvokeTreeSceSynthInvokeWorkerClock(on engine: Engine<StaticInvokeTreeSceSynthInvokeWorkerPolicy>, token: UInt64, result: StaticInvokeTreeSceSynthInvokeWorkerClockResult) -> Bool {
    engine.completeHostInvoke(processorType: "sce-host-clock-now", invokeID: "clock", token: token, doneData: result.wire)
}


